#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static size_t chars(const char *s) {
    size_t n = 0;
    for (; *s; s++)
        if (((unsigned char)*s & 192) != 128)
            n++;
    return n;
}
static size_t prefix(const char *s, size_t n) {
    size_t bytes = 0, count = 0;
    while (s[bytes]) {
        if (((unsigned char)s[bytes] & 192) != 128) {
            if (count == n)
                break;
            count++;
        }
        bytes++;
    }
    return bytes;
}
static int cmp(const void *a, const void *b) {
    const entry *x = (const entry *)a, *y = (const entry *)b;
    if (x->year != y->year)
        return x->year < y->year ? -1 : 1;
    if (x->month != y->month)
        return x->month - y->month;
    if (x->day != y->day)
        return x->day - y->day;
    if (x->change != y->change)
        return x->change < y->change ? -1 : 1;
    return strcmp(x->description, y->description);
}
char *format_entries(const char *cur, const char *loc, const entry *e, size_t n) {
    bool nl = !strcmp(loc, "nl_NL");
    if ((!nl && strcmp(loc, "en_US")) || (strcmp(cur, "USD") && strcmp(cur, "EUR")))
        return NULL;
    entry *v = (entry *)malloc(n * sizeof(entry));
    if (n)
        memcpy(v, e, n * sizeof(entry));
    qsort(v, n, sizeof(entry), cmp);
    size_t cap = 100;
    for (size_t i = 0; i < n; i++)
        cap += strlen(e[i].description) + 150;
    char *out = (char *)malloc(cap);
    strcpy(out, nl ? "Datum      | Omschrijving              | Verandering  "
                   : "Date       | Description               | Change       ");
    for (size_t i = 0; i < n; i++) {
        char date[40], desc[104], num[100], money[140], digits[100];
        if (nl)
            snprintf(date, 40, "%02d-%02d-%04d", v[i].day, v[i].month, v[i].year);
        else
            snprintf(date, 40, "%02d/%02d/%04d", v[i].month, v[i].day, v[i].year);
        size_t dl = chars(v[i].description);
        if (dl > 25) {
            size_t bytes = prefix(v[i].description, 22);
            memcpy(desc, v[i].description, bytes);
            strcpy(desc + bytes, "...");
        } else
            strcpy(desc, v[i].description);
        uint64_t value = v[i].change < 0 ? (uint64_t)(-(v[i].change + 1)) + 1
                                         : (uint64_t)v[i].change;
        snprintf(digits, 100, "%llu", (unsigned long long)(value / 100));
        size_t len = strlen(digits), k = 0;
        for (size_t j = 0; j < len; j++) {
            if (j && (len - j) % 3 == 0)
                num[k++] = nl ? '.' : ',';
            num[k++] = digits[j];
        }
        snprintf(num + k, 100 - k, "%c%02u", nl ? ',' : '.', (unsigned)(value % 100));
        const char *symbol = !strcmp(cur, "USD") ? "$" : "€";
        if (nl)
            snprintf(money, 140, "%s %s%s ", symbol, v[i].change < 0 ? "-" : "", num);
        else
            snprintf(money, 140, "%s%s%s%s", v[i].change < 0 ? "(" : "", symbol, num,
                     v[i].change < 0 ? ")" : " ");
        size_t ml = strlen(money) - (!strcmp(cur, "EUR") ? 2 : 0);
        sprintf(out + strlen(out), "\n%-10s | %-*s | %*s%s", date,
                (int)(25 + strlen(desc) - chars(desc)), desc,
                ml < 13 ? (int)(13 - ml) : 0, "", money);
    }
    free(v);
    return out;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    entry e[] = {{2015, 1, 1, "Buy present", -1000},
                 {2015, 1, 2, "Get present", 123456}};
    char *s = format_entries("USD", "en_US", e, 2);
    assert(strstr(s, "01/01/2015 | Buy present               |      ($10.00)"));
    assert(strstr(s, "$1,234.56 "));
    free(s);
    s = format_entries("EUR", "nl_NL", e, 2);
    assert(strstr(s, "01-01-2015") && strstr(s, "€ -10,00 "));
    free(s);
    s = format_entries("USD", "en_US", NULL, 0);
    assert(!strcmp(s, "Date       | Description               | Change       "));
    free(s);
    {
        entry values[] = {{0, 0, 0, NULL, 0}};
        char *actual = format_entries("USD", "en_US", values, 0);
        assert(
            !strcmp(actual, "Date       | Description               | Change       "));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 1, "Buy present", -1000}};
        char *actual = format_entries("USD", "en_US", values, 1);
        assert(!strcmp(actual,
                       "Date       | Description               | Change       "
                       "\n01/01/2015 | Buy present               |      ($10.00)"));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 2, "Get present", 1000},
                          {2015, 1, 1, "Buy present", -1000}};
        char *actual = format_entries("USD", "en_US", values, 2);
        assert(!strcmp(
            actual,
            "Date       | Description               | Change       \n01/01/2015 | Buy "
            "present               |      ($10.00)\n01/02/2015 | Get present           "
            "    |       $10.00 "));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 1, "Something", 0},
                          {2015, 1, 1, "Something", -1},
                          {2015, 1, 1, "Something", 1}};
        char *actual = format_entries("USD", "en_US", values, 3);
        assert(!strcmp(actual,
                       "Date       | Description               | Change       "
                       "\n01/01/2015 | Something                 |       "
                       "($0.01)\n01/01/2015 | Something                 |        $0.00 "
                       "\n01/01/2015 | Something                 |        $0.01 "));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 1, "Freude schoner Gotterfunken", -123456}};
        char *actual = format_entries("USD", "en_US", values, 1);
        assert(!strcmp(actual,
                       "Date       | Description               | Change       "
                       "\n01/01/2015 | Freude schoner Gotterf... |   ($1,234.56)"));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 1, "Buy present", -1000}};
        char *actual = format_entries("EUR", "en_US", values, 1);
        assert(!strcmp(actual,
                       "Date       | Description               | Change       "
                       "\n01/01/2015 | Buy present               |      (€10.00)"));
        free(actual);
    }
    {
        entry values[] = {{2015, 3, 12, "Buy present", 123456}};
        char *actual = format_entries("USD", "nl_NL", values, 1);
        assert(!strcmp(actual,
                       "Datum      | Omschrijving              | Verandering  "
                       "\n12-03-2015 | Buy present               |   $ 1.234,56 "));
        free(actual);
    }
    {
        entry values[] = {{2015, 3, 12, "Buy present", 123456}};
        char *actual = format_entries("EUR", "nl_NL", values, 1);
        assert(!strcmp(actual,
                       "Datum      | Omschrijving              | Verandering  "
                       "\n12-03-2015 | Buy present               |   € 1.234,56 "));
        free(actual);
    }
    {
        entry values[] = {{2015, 3, 12, "Buy present", -12345}};
        char *actual = format_entries("USD", "nl_NL", values, 1);
        assert(!strcmp(actual,
                       "Datum      | Omschrijving              | Verandering  "
                       "\n12-03-2015 | Buy present               |    $ -123,45 "));
        free(actual);
    }
    {
        entry values[] = {{2015, 3, 12, "Buy present", -12345}};
        char *actual = format_entries("USD", "en_US", values, 1);
        assert(!strcmp(actual,
                       "Date       | Description               | Change       "
                       "\n03/12/2015 | Buy present               |     ($123.45)"));
        free(actual);
    }
    {
        entry values[] = {{2015, 1, 1, "Get present", 1000},
                          {2015, 1, 1, "Buy present", -1000}};
        char *actual = format_entries("USD", "en_US", values, 2);
        assert(!strcmp(
            actual,
            "Date       | Description               | Change       \n01/01/2015 | Buy "
            "present               |      ($10.00)\n01/01/2015 | Get present           "
            "    |       $10.00 "));
        free(actual);
    }
    return 0;
}
